// spec: specs/orders.md §33 · кейс .qa/tests/orders/ord-46 · seed: tests/seed.admin.spec.ts
// #a597e8 (commit 79a6260): /orders/<id>/receipt — текст зависит от заказа. מכירה מיידית → «למכירה מיידית לא מופקת קבלה — אישור המכירה הוא
//   המסמך שלה.» (без «קבלה מופקת אוטומטית באישור ההזמנה»); ממתינה לאישור → «להזמנה זו עדיין אין קבלה. קבלה מופקת אוטומטית באישור ההזמנה.»;
//   נדחתה (#559) → «להזמנה שנדחתה לא מופקת קבלה.»; утверждён до קבלות (#504) → «ההזמנה אושרה לפני שהמערכת התחילה להפיק קבלות, ולכן אין לה קבלה.»;
//   «חזרה להזמנה» ведёт на карточку.
// Заказы — по номеру через /orders/<номер> (редирект на uuid, #de732f). Ничего не создаёт — @prod-safe.
// Если данных нужного типа нет (особенно «ממתינה לאישור») — test.skip с причиной.
import { test, expect, Page } from '@playwright/test';
import * as path from 'path';

test.use({ storageState: path.resolve(__dirname, '../../../auth/admin.json') });

const UUID_PATH = /\/orders\/[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/;
const INSTANT_CANDIDATES = [634, 659, 636, 639];
const TXT = {
  instant: 'למכירה מיידית לא מופקת קבלה — אישור המכירה הוא המסמך שלה.',
  pending: 'להזמנה זו עדיין אין קבלה. קבלה מופקת אוטומטית באישור ההזמנה.',
  rejected: 'להזמנה שנדחתה לא מופקת קבלה.',
  legacy: 'ההזמנה אושרה לפני שהמערכת התחילה להפיק קבלות, ולכן אין לה קבלה.',
};
const PROMISE = 'קבלה מופקת אוטומטית באישור ההזמנה';

/** /orders/<номер> → путь карточки (/orders/<uuid>) или null, если «ההזמנה לא נמצאה.». */
async function cardByNumber(page: Page, n: number): Promise<string | null> {
  await page.goto(`/orders/${n}`);
  const main = page.getByRole('main');
  const heading = main.getByRole('heading', { name: `הזמנה #${n}` });
  const missing = main.getByText('ההזמנה לא נמצאה.', { exact: true });
  await expect(heading.or(missing)).toBeVisible({ timeout: 30_000 });
  if (await missing.isVisible()) return null;
  await expect(page).toHaveURL(UUID_PATH);
  return new URL(page.url()).pathname;
}

async function openReceipt(page: Page, card: string) {
  await page.goto(`${card}/receipt`);
  await expect(page.getByRole('main').getByText('חזרה להזמנה', { exact: true })).toBeVisible({ timeout: 30_000 });
}

/** Сообщение на /receipt: ровно этот текст, без «נסה שוב». */
async function expectMessage(page: Page, text: string) {
  const main = page.getByRole('main');
  await expect(main.getByText(text, { exact: true })).toBeVisible({ timeout: 20_000 });
  await expect(page.getByText('נסה שוב')).toHaveCount(0);
}

async function instantSaleCard(page: Page): Promise<string | null> {
  for (const n of INSTANT_CANDIDATES) {
    const card = await cardByNumber(page, n);
    if (card && (await page.getByRole('main').getByText(/מכירה מיידית/).first().isVisible())) return card;
  }
  return null;
}

test.describe('/orders/<id>/receipt — הודעה לפי סוג ההזמנה (#a597e8)', () => {
  test('מכירה מיידית: «למכירה מיידית לא מופקת קבלה — אישור המכירה הוא המסמך שלה.», בלי «קבלה מופקת אוטומטית באישור ההזמנה» #a597e8 @desktop @prod-safe', async ({ page }) => {
    const card = await instantSaleCard(page);
    test.skip(!card, `нет «מכירה מיידית» среди #${INSTANT_CANDIDATES.join(', #')} — взять другой номер`);
    await openReceipt(page, card!);
    await expectMessage(page, TXT.instant);
    await expect(page.getByText(PROMISE), 'нет ложного обещания «…באישור ההזמנה»').toHaveCount(0);
  });

  test('ממתינה לאישור: «להזמנה זו עדיין אין קבלה. קבלה מופקת אוטומטית באישור ההזמנה.» #a597e8 @desktop @prod-safe', async ({ page }) => {
    await page.goto('/orders');
    await page.getByRole('combobox', { name: 'סינון לפי חודש' }).selectOption({ label: 'כל החודשים' });
    const row = page.getByRole('button', { name: /^#\d+ / }).filter({ hasText: 'ממתינה לאישור' }).first();
    await expect(page.getByRole('button', { name: /^#\d+ / }).first()).toBeVisible({ timeout: 30_000 });
    test.skip((await row.count()) === 0, 'нет заказа «ממתינה לאישור» — создать/дождаться (заказ buyer до «אשר הזמנה»)');
    await row.click();
    await expect(page).toHaveURL(UUID_PATH, { timeout: 20_000 });
    const card = new URL(page.url()).pathname;
    await openReceipt(page, card);
    await expectMessage(page, TXT.pending);
  });

  test('נדחתה (#559): «להזמנה שנדחתה לא מופקת קבלה.» #a597e8 @desktop @prod-safe', async ({ page }) => {
    const card = await cardByNumber(page, 559);
    test.skip(!card, 'заказ #559 не найден');
    test.skip(!(await page.getByRole('main').getByText(/נדחתה/).first().isVisible()), '#559 больше не «נדחתה»');
    await openReceipt(page, card!);
    await expectMessage(page, TXT.rejected);
  });

  test('אושרה לפני הפקת קבלות (#504): «ההזמנה אושרה לפני שהמערכת התחילה להפיק קבלות, ולכן אין לה קבלה.» #a597e8 @desktop @prod-safe', async ({ page }) => {
    const card = await cardByNumber(page, 504);
    test.skip(!card, 'заказ #504 не найден');
    await openReceipt(page, card!);
    await expectMessage(page, TXT.legacy);
  });

  test('«חזרה להזמנה» מוביל לכרטיס ההזמנה #a597e8 @desktop @prod-safe', async ({ page }) => {
    const card = await instantSaleCard(page);
    test.skip(!card, 'нет «מכירה מיידית» среди кандидатов');
    await openReceipt(page, card!);
    await page.getByRole('main').getByText('חזרה להזמנה', { exact: true }).click();
    await expect(page).toHaveURL(UUID_PATH, { timeout: 20_000 });
    expect(new URL(page.url()).pathname, 'вернулись в ту же карточку').toBe(card);
    await expect(page.getByRole('heading', { name: /^הזמנה #\d+$/ })).toBeVisible({ timeout: 20_000 });
  });
});
